// HapticStyle enum for type safety
const HapticStyle = {
  LIGHT: 'light',
  MEDIUM: 'medium',
  HEAVY: 'heavy',
  SUCCESS: 'success',
  WARNING: 'warning',
  ERROR: 'error',
}

class RundotGameAPI {
  constructor() {
    // Shared configuration
    this._shared = {
      initialized: false,
      initPromise: null,
    }

    // Bootstrap-specific properties
    this._bootstrap = {
      apiInjected: false,
      apiInjectionTimeout: null,
      rundotGame: null,
      isInsideHostedEnvironment: false,
      _localHandlers: {}, // Store local handlers here
      _pendingMessages: [], // Buffer messages until handlers are registered
    }

    // Generate deterministic instance ID based on current URL
    const deterministicInstanceId = this._generateDeterministicInstanceId()

    // Mock data structure matching real config format
    this._mock = {
      // Essential config (matching H5ConfigProperties)
      appId: 'mock-app',
      mode: 'preview',
      instanceId: deterministicInstanceId, // Use deterministic ID instead of random
      appUrl: 'mock-app/index.html',
      safeAreaInsets: {
        top: 10,
        right: 0,
        bottom: 10,
        left: 0,
      },
      // NOTE: locale and languageCode are NOT part of static config
      // They are delivered via INIT_SDK handshake and accessed via getLocale()/getLanguageCode()
      // Complete environment info (matching buildStaticConfig)
      environment: {
        isDevelopment: true,
        platform: 'web',
        platformVersion: 'mock-1.0',
        browserInfo: {
          browser: 'MockBrowser',
          userAgent: navigator.userAgent,
          isMobile: /Mobi|Android/i.test(navigator.userAgent),
          isTablet: /iPad|Tablet|Pad/i.test(navigator.userAgent),
          language: navigator.language || 'en-US',
        },
      },
      // Complete device info (matching buildStaticConfig)
      device: {
        screenSize: { width: window.innerWidth, height: window.innerHeight },
        viewportSize: {
          width: window.innerWidth - 20, // account for safe area
          height: window.innerHeight - 20,
        },
        orientation:
          window.innerWidth > window.innerHeight ? 'landscape' : 'portrait',
        pixelRatio: window.devicePixelRatio || 1,
        fontScale: 1,
        deviceType: window.innerWidth > 768 ? 'tablet' : 'phone',
        platform: 'web',
        isWeb: true,
        isMobile: /Mobi|Android/i.test(navigator.userAgent),
        hapticsEnabled: false, // Mock environment doesn't support haptics
        haptics: {
          supported: false,
          enabled: false,
        },
      },
      // Context structure (matching buildStaticConfig)
      context: {
        postData: undefined,
        stack: {
          isInStack: false,
          stackPosition: 0,
          parentInstanceId: undefined,
        },
      },

      // Internal state (existing handlers and interaction data)
      handlers: {
        onPlay: null,
        onPause: null,
        onResume: null,
        onQuit: null,
        onHide: null,
        onShow: null,
      },

      // Platform overrides for testing different environments
      platformOverrides: {
        isMobile: true,
        isWeb: false,
      },
    }

    // Merge dev-server-injected mock fixtures (top-level keys only) over the
    // defaults above. The Vite plugin populates this from on-disk config in serve
    // mode — today `{ liveops: <rundot/liveops.config.json> }`, consumed by
    // MockHost so mock mode serves your real LiveOps config with no backend.
    if (typeof window !== 'undefined' && window.__RUNDOT_GAME_MOCK__) {
      Object.assign(this._mock, window.__RUNDOT_GAME_MOCK__)
    }

    // Detect if we're inside a hosted environment (iframe or WebView)
    this._detectHostedEnvironment()

    this.config = createProxiedObject.call(this, 'config', {})

    const originalConfig = this.config
    const self = this
    this.config = new Proxy(originalConfig, {
      get(target, prop) {
        if (prop === 'locale') {
          throw new Error('Use RundotGameAPI.getLocale() instead.')
        }
        
        if (prop === 'languageCode') {
          throw new Error('Use RundotGameAPI.getLanguageCode() instead.')
        }
        
        if (prop === 'user') {
          throw new Error('Use RundotGameAPI.getLocale() and RundotGameAPI.getLanguageCode() instead.')
        }
        
        if (prop === 'device') {
          throw new Error('Use RundotGameAPI.system.getDevice() instead.')
        }
        
        if (prop === 'environment') {
          throw new Error('Use RundotGameAPI.system.getEnvironment() instead.')
        }
        
        if (prop === 'profile') {
          throw new Error('Use RundotGameAPI.getProfile() instead.')
        }
        
        if (prop === 'rooms') {
          throw new Error('Rooms configuration is internal. Realtime (RundotGameAPI.realtime) is the supported multiplayer API.')
        }
        
        if (prop === 'ui') {
          return new Proxy({}, {
            get(uiTarget, uiProp) {
              if (uiProp === 'safeArea') {
                throw new Error('Use RundotGameAPI.system.getSafeArea() instead.')
              }
              
              if (uiProp === 'hudInsets') {
                throw new Error('Use RundotGameAPI.system.getSafeArea() instead.')
              }
              
              if (uiProp === 'controls') {
                throw new Error('UI controls are no longer supported.')
              }
              
              throw new Error(`RundotGameAPI.config.ui.${uiProp} is not supported.`)
            }
          })
        }
        
        return target[prop]
      },
      set(target, prop, value) {
        if (prop === 'locale' || prop === 'languageCode' || prop === 'user' || 
            prop === 'device' || prop === 'environment' || prop === 'profile') {
          throw new Error(`RundotGameAPI.config.${prop} cannot be set. Configuration is read-only.`)
        }
        if (prop === 'ui') {
          console.warn('[RUN] Cannot set config.ui')
          return true
        }
        target[prop] = value
        return true
      },
      has(target, prop) {
        if (prop === 'ui') {
          return false
        }
        return prop in target
      },
      ownKeys(target) {
        // Hide 'ui' from Object.keys(), Object.getOwnPropertyNames(), etc.
        return Reflect.ownKeys(target).filter(key => key !== 'ui')
      },
      getOwnPropertyDescriptor(target, prop) {
        // Make proxy properties appear to not exist for enumeration
        if (prop === 'ui') {
          return undefined
        }
        return Reflect.getOwnPropertyDescriptor(target, prop)
      }
    })

    // Host is created asynchronously to allow dynamic import of PlaygroundHost.
    // This is critical: PlaygroundHost imports Firebase (~200KB+) which should
    // ONLY be loaded during development (playground mode), not in production builds.
    // See Host.ts for detailed explanation of why dynamic import is required.
    this._hostPromise = this._createHostAsync()

    // Initialize asset loader functionality (doesn't depend on host)
    initializeAssetLoader(this, createProxiedMethod)

    this.getLocale = () => {
      if (this._localeData) {
        return this._localeData
      }
      
      if (typeof navigator !== 'undefined' && navigator.language) {
        return navigator.language
      }
      
      return 'en-US'
    }

    this.getLanguageCode = () => {
      if (this._languageCodeData) {
        return this._languageCodeData
      }
      
      const locale = this.getLocale()
      return locale.split('-')[0]
    }
  }

  // Generate deterministic instance ID based on current page URL
  _generateDeterministicInstanceId() {
    try {
      // Get current URL and normalize it like H5IdUtils does
      let url = window.location.href || ''

      // Normalize URL to match H5IdUtils.normalizeAppUrl logic:
      // 1. Remove protocol, domain, port
      let normalizedUrl = url.replace(/^https?:\/\/[^\/]+/, '')

      // 2. Remove query parameters and hash fragments
      normalizedUrl = normalizedUrl.split('?')[0].split('#')[0].trim()

      // 3. Ensure it starts with /H5/ for consistency
      if (
        !normalizedUrl.startsWith('/H5/') &&
        !normalizedUrl.startsWith('H5/')
      ) {
        // If it's just the app name, assume it's in /H5/
        if (!normalizedUrl.includes('/')) {
          normalizedUrl = `/H5/${normalizedUrl}/index.html`
        } else if (!normalizedUrl.startsWith('/')) {
          normalizedUrl = `/${normalizedUrl}`
        }
      }

      // Normalized URL for deterministic hashing

      // Create hash from normalized URL (same logic as H5IdUtils)
      let hash = 0
      for (let i = 0; i < normalizedUrl.length; i++) {
        const char = normalizedUrl.charCodeAt(i)
        hash = (hash << 5) - hash + char
        hash = hash & hash // Convert to 32-bit integer
      }

      // Convert to positive base36 and ensure 8 characters (same as H5IdUtils)
      const hashB36 = Math.abs(hash).toString(36)
      const paddedHash = hashB36.substring(0, 8).padEnd(8, '0')

      const deterministicId = `app-${paddedHash}`

      // Generated deterministic instance ID

      return deterministicId
    } catch (error) {
      console.error(
        '[RUN] Error generating deterministic ID, falling back to random:',
        error,
      )
      // Fallback to improved random ID if deterministic generation fails
      return 'app-' + Math.random().toString(36).substr(2, 8)
    }
  }

  //---------------------------------------
  // BOOTSTRAP METHODS
  //---------------------------------------

  _detectHostedEnvironment() {
    this._bootstrap.isInsideHostedEnvironment = isInsideHostedEnvironment(
      typeof window !== 'undefined' ? window : undefined,
    )
  }

  //---------------------------------------
  // HOST CREATION (async for dynamic imports)
  //---------------------------------------

  /**
   * Create and initialize the Host asynchronously.
   *
   * This is async because createHost uses dynamic import for PlaygroundHost,
   * which prevents Firebase from being bundled in production builds.
   */
  async _createHostAsync() {
    const isInsideHostedEnv = this._bootstrap.isInsideHostedEnvironment
    const host = await createHost(this, !isInsideHostedEnv)
    this.host = host

    // Now initialize all subsystems that depend on host
    initializeStorage(this, host)
    initializeRoomsApi(this, host)
    initializeAds(this, host)
    initializePopups(this, host)
    initializeAnalytics(this, host)
    initializeIap(this, host)
    initializeCredits(this, host)
    initializeLeaderboard(this, host)
    initializeUgc(this, host)
    initializeLocalNotifications(this, host)
    initializePreloader(this, host)
    initializeTime(this, host)
    initializeLifecycleApi(this, host)
    initializeHaptics(this, host)
    initializeGamepad(this, host)
    initializeCdn(this, host)
    initializeFeaturesApi(this, host)
    initializeLoggingApi(this, host)

    const isAvatar3dDisabled =
      typeof window !== 'undefined' &&
      window.location.search.includes('EXPO_PUBLIC_DISABLE_3D_AVATARS=true')

    initializeProfile(this, host)
    initializeSystem(this, host)

    if (!isAvatar3dDisabled) {
      initializeAvatar3d(this, host)
    }

    initializeStackNavigation(this, host)
    initializeTextGen(this, host)
    initializeAi(this, host)
    initializeImageGen(this, host)
    initializeAudioGen(this, host)
    initializeVideoGen(this, host)
    initializeFiles(this, host)
    initializeClips(this, host)
    initializeSpriteGen(this, host)
    initializeThreeDGen(this, host)
    initializeSimulation(this, host)
    initializeLiveOps(this, host)
    initializeSocial(this, host)
    initializeEntitlements(this, host)
    initializeChoices(this, host)
    initializeStats(this, host)
    initializeCollectibles(this, host)
    initializeShop(this, host)
    initializeAccessGate(this, host)
    initializeMultiplayerApi(this, host)
    initializeVideo(this, host)
    initializeActivity(this, host)
    initializeApp(this, host)
    initializeAttribution(this, host)

    return host
  }

  //---------------------------------------
  // PUBLIC API METHODS
  //---------------------------------------


  /**
   * @deprecated No longer need to call this method. This will get called on import.
   */
  async initializeAsync() {
    // If already initialized successfully, resolve immediately.
    if (this._shared.initialized) {
      return Promise.resolve(this.host.context)
    }

    if (this._shared.initPromise) {
      return this._shared.initPromise
    }

    this._shared.initPromise = new Promise(async (resolve, reject) => {
      try {
        // Wait for host to be created (async due to dynamic import)
        await this._hostPromise
        const result = await this.host.initialize()
        // Initialize context AFTER host.initialize() so host.context is populated
        initializeContext(this, this.host)

        const heartbeat = new HeartbeatService(new PostMessageHeartbeatTransport(this.host.instanceId))
        heartbeat.attach()
        if (!result.initializeAsleep) {
          heartbeat.start()
        }

        this._shared.initialized = true
        resolve(result)
      } catch (err) {
        reject(err)
      }
    })

    return this._shared.initPromise
  }
}

// Create singleton instance
const instance = new RundotGameAPI()

// Export for module usage
export default instance

// Also attach to window for non-module environments
window.RundotGameAPI = instance

// Export HapticStyle enum for RUN.world apps to use
instance.HapticStyle = HapticStyle

// Add isAvailable utility method for RUN.world games
instance.isAvailable = function () {
  try {
    return !!(typeof window !== 'undefined' && window.RundotGameAPI) || !!this
  } catch {
    return false
  }
}

try {
  await initializeNumbers(instance)
} catch (error) {
  console.error('[RUN] Failed to initialize numbers system:', error)
}

try {
  await instance.initializeAsync()
  instance.log(`[RUN] v${SDK_VERSION} initialized.`)
} catch (error) {
  console.error('[RUN] Failed to initialize RUN.world SDK:', error)
}
