// H5 Big Number System - RUN.world API
// Provides break_eternity.js functionality to H5 games

// Import break_eternity.js as ES6 module from local file (default export)
import Decimal from '../lib/break_eternity.js';

function createNumbersAPI() {
  // Create the numbers API
  const numbersAPI = {
    // Type detection helper
    isBigNumber: (value) => {
      if (typeof value === 'string' && value.startsWith('BE:')) return true;
      if (value instanceof Decimal) return true;
      if (typeof value === 'number' && (value > Number.MAX_SAFE_INTEGER || value < Number.MIN_SAFE_INTEGER)) return true;
      return false;
    },
    
    // Normalize any input to Decimal (for API responses)
    normalize: (value) => {
      if (value instanceof Decimal) return value;
      if (typeof value === 'string' && value.startsWith('BE:')) {
        return new Decimal(value.slice(3));
      }
      return new Decimal(value);
    },
    
    // Common game formatters
    format: {
      incremental: (value) => {
        const decimal = value instanceof Decimal ? value : new Decimal(value);
        const suffixes = ['', 'K', 'M', 'B', 'T', 'Qa', 'Qi', 'Sx', 'Sp', 'Oc', 'No', 'Dc'];
        
        if (decimal.lt(1000)) return decimal.toFixed(0);
        
        const log = decimal.log10();
        const suffixIndex = Math.floor(log / 3);
        
        if (suffixIndex < suffixes.length) {
          const divisor = Decimal.pow(1000, suffixIndex);
          const value = decimal.div(divisor);
          return `${value.toFixed(2)}${suffixes[suffixIndex]}`;
        }
        
        return decimal.toExponential(2);
      }
    },
    
    // NEW: Calculate geometric series cost with full Decimal precision
    calculateGeometricSeriesCost: (baseCost, multiplier, currentQuantity, purchaseAmount) => {
      try {
        const base = new Decimal(baseCost);
        const r = new Decimal(multiplier);
        const q = new Decimal(currentQuantity);
        const n = new Decimal(purchaseAmount);

        if (r.eq(1)) {
          // Linear progression: baseCost * n
          return base.mul(n);
        }

        // Geometric series: a * (r^n - 1) / (r - 1)
        // where a = baseCost * r^currentQuantity
        const a = base.mul(r.pow(q));
        const numerator = a.mul(r.pow(n).sub(1));
        const denominator = r.sub(1);
        
        return numerator.div(denominator);
      } catch (error) {
        console.error('[RUN] Decimal calculation failed, falling back to regular math:', error);
        // Fallback to regular JavaScript math
        const base = Number(baseCost);
        const r = Number(multiplier);
        if (r === 1) return base * purchaseAmount;
        const a = base * Math.pow(r, currentQuantity);
        return (a * (Math.pow(r, purchaseAmount) - 1)) / (r - 1);
      }
    },

    // NEW: Find maximum affordable amount using Decimal precision
    calculateMaxAffordableDecimal: (availableCash, baseCost, multiplier, currentQuantity) => {
      try {
        const cash = new Decimal(availableCash);
        
        // Quick check if even one is affordable
        const costOne = numbersAPI.calculateGeometricSeriesCost(baseCost, multiplier, currentQuantity, 1);
        if (cash.lt(costOne)) return 0;

        // Binary search with Decimal precision
        let low = 1;
        let high = 1;

        // Find upper bound (exponential search)
        while (high < 1000000) { // Safety limit
          const cost = numbersAPI.calculateGeometricSeriesCost(baseCost, multiplier, currentQuantity, high);
          if (cost.gt(cash)) break;
          low = high;
          high *= 2;
        }

        // Binary search for exact maximum
        while (low < high) {
          const mid = Math.floor((low + high + 1) / 2);
          const cost = numbersAPI.calculateGeometricSeriesCost(baseCost, multiplier, currentQuantity, mid);
          
          if (cost.lte(cash)) {
            low = mid;
          } else {
            high = mid - 1;
          }
        }

        return low;
      } catch (error) {
        console.error('[RUN] Decimal max affordable calculation failed:', error);
        // Fallback to simple division
        return Math.floor(Number(availableCash) / Number(baseCost));
      }
    },

    // NEW: Format Decimal value for currency display
    formatDecimalCurrency: (decimalValue) => {
      try {
        if (numbersAPI.isBigNumber(decimalValue)) {
          return `$${numbersAPI.format.incremental(decimalValue)}`;
        }
        // Fallback for regular numbers
        return `$${numbersAPI.format.incremental(decimalValue)}`;
      } catch (error) {
        console.error('[RUN] Decimal formatting failed:', error);
        return `$${Number(decimalValue).toLocaleString()}`;
      }
    }
  };

  // Initialized with break_eternity.js
  
  return numbersAPI;
}

// Export initialization function for rundot-game-api/index.js
export async function initializeNumbers(rundotGameApiInstance) {
  // Initializing numbers system...
  
  // Import createProxiedObject and createProxiedMethod from core
  const { createProxiedObject, createProxiedMethod } = await import('./core.js');
  
  // Create the numbers API (Decimal is already imported as ES6 module)
  const numbersAPI = createNumbersAPI();
  
  // Add numbers API to RundotGameAPI instance
  rundotGameApiInstance.numbers = createProxiedObject.call(
    rundotGameApiInstance,
    'numbers',
    {
      isBigNumber: numbersAPI.isBigNumber,
      normalize: numbersAPI.normalize,
      format: {
        incremental: numbersAPI.format.incremental
      },
      // NEW: Expose geometric series calculation methods
      calculateGeometricSeriesCost: numbersAPI.calculateGeometricSeriesCost,
      calculateMaxAffordableDecimal: numbersAPI.calculateMaxAffordableDecimal,
      formatDecimalCurrency: numbersAPI.formatDecimalCurrency,
      // Expose Decimal class for direct use
      Decimal: Decimal
    }
  );
  
  // Numbers system initialized with break_eternity.js
}

// Export Decimal for direct use in games
export { Decimal };