/**
 * RUN.world Asset Loader - Unified asset loading for all H5 apps
 * Simplifies complex asset loading with automatic WebView handling, streaming support, and caching
 */

class RundotGameAssetLoader {
  constructor() {
    this.cache = new Map();
    this.blobUrls = new Map();
    // Will be set during initialization when RundotGameAPI is available
    this.isWebView = false;
    this.rundotGameAPI = null;
  }

  // Set the RundotGameAPI reference during initialization
  setRundotGameAPI(api) {
    this.rundotGameAPI = api;
    // Detect WebView directly without calling RundotGameAPI methods (which require initialization)
    this.isWebView = typeof window !== 'undefined' && typeof window.ReactNativeWebView !== 'undefined';
  }

  /**
   * Load any asset with automatic optimization
   * @param {string} url - Asset URL
   * @param {Object} options - Loading options
   * @returns {Promise<string>} - URL to use (original, blob, or object URL)
   */
  async loadAsset(url, options = {}) {
    const {
      type = 'auto', // 'image', 'audio', 'video', 'text', 'json', 'auto'
      cache = true, // Use cache
      timeout = 30000,
      isOptional = false // New option to suppress error logging for optional assets
    } = options;

    // Resolve the URL to ensure it has proper CDN prefix if needed
    const resolvedUrl = await this.rundotGameAPI.cdn.resolveAssetUrl(url);

    // Check cache first
    if (cache && this.cache.has(resolvedUrl)) {
      return this.cache.get(resolvedUrl);
    }

    // Auto-detect type if needed
    const assetType = type === 'auto' ? this._detectType(resolvedUrl) : type;

    try {
      let resultUrl = resolvedUrl;

      // Text/JSON always fetched directly
      if (assetType === 'text' || assetType === 'json') {
        const content = await this._fetchText(resolvedUrl, timeout);
        this.cache.set(resolvedUrl, content);
        return content;
      }

      // Skip blob loading in mock mode (development)
      const isMockMode = this.rundotGameAPI && this.rundotGameAPI.isMock && this.rundotGameAPI.isMock();
      
      // For media assets in WebView (but not mock mode), decide between streaming and blob
      if (this.isWebView && !isMockMode && ['image', 'audio', 'video'].includes(assetType)) {
        // Always use blob loading for videos in WebView to avoid streaming issues
        if (assetType === 'video') {
          resultUrl = await this._loadAsBlob(resolvedUrl, assetType);
          // Skip verification for blob videos - they're already verified during blob creation
          if (cache) {
            this.cache.set(resolvedUrl, resultUrl);
          }
          return resultUrl;
        } else if (assetType === 'audio') {
          // Audio also uses blob loading in WebView
          resultUrl = await this._loadAsBlob(resolvedUrl, assetType);
        } else {
          // Images use blob loading in WebView
          resultUrl = await this._loadAsBlob(resolvedUrl, assetType);
        }
      }

      // Verify the asset can be loaded (skip for WebView videos handled above)
      if (!(this.isWebView && !isMockMode && assetType === 'video')) {
        await this._verifyAsset(resultUrl, assetType);
      }

      if (cache) {
        this.cache.set(resolvedUrl, resultUrl);
      }

      return resultUrl;
    } catch (error) {
      // Only log errors for required assets
      if (!isOptional) {
        console.error(`[RUN:assets] Failed to load ${resolvedUrl}:`, error);
      }
      throw error;
    }
  }

  async _fetchText(url, timeout) {
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), timeout);

    try {
      const response = await fetch(url, { signal: controller.signal });

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      return await response.text();
    } catch (error) {
      clearTimeout(timeoutId);
      throw error;
    }
  }

  async _loadAsBlob(url, type) {
    // Check if we already have a blob URL for this asset
    if (this.blobUrls.has(url)) {
      return this.blobUrls.get(url);
    }

    const mimeType = {
      image: 'image/*',
      audio: 'audio/*',
      video: 'video/*'
    }[type] || '*/*';

    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 30000);

    try {
      // Always use native fetch for blob loading since RundotGameAPI doesn't support blob()
      const response = await fetch(url, {
        mode: 'cors',
        credentials: 'omit',
        headers: { Accept: mimeType },
        signal: controller.signal
      });

      clearTimeout(timeoutId);

      if (!response.ok) {
        throw new Error(`HTTP ${response.status}: ${response.statusText}`);
      }

      const blob = await response.blob();
      const blobUrl = URL.createObjectURL(blob);
      
      // Track blob URL for cleanup
      this.blobUrls.set(url, blobUrl);
      
      return blobUrl;
    } catch (error) {
      clearTimeout(timeoutId);
      throw error;
    }
  }

  async _checkStreamingSupport(url) {
    try {
      const response = await fetch(url, { method: 'HEAD' });

      const acceptRanges = response.headers.get('Accept-Ranges') === 'bytes';
      const contentLength = response.headers.get('Content-Length');
      
      return acceptRanges && !!contentLength;
    } catch {
      return false;
    }
  }

  async _verifyAsset(url, type) {
    return new Promise((resolve, reject) => {
      const timeout = setTimeout(() => {
        reject(new Error(`Verification timeout for ${type} asset`));
      }, 10000);

      if (type === 'image') {
        const img = new Image();
        img.onload = () => {
          clearTimeout(timeout);
          resolve();
        };
        img.onerror = (error) => {
          clearTimeout(timeout);
          reject(new Error('Failed to load image'));
        };
        img.src = url;
      } else if (type === 'audio') {
        const audio = new Audio();
        audio.oncanplaythrough = () => {
          clearTimeout(timeout);
          resolve();
        };
        audio.onerror = () => {
          clearTimeout(timeout);
          reject(new Error('Failed to load audio'));
        };
        audio.src = url;
        audio.load();
      } else if (type === 'video') {
        const video = document.createElement('video');
        video.onloadedmetadata = () => {
          clearTimeout(timeout);
          video.src = ''; // Clean up
          resolve();
        };
        video.onerror = () => {
          clearTimeout(timeout);
          reject(new Error('Failed to load video'));
        };
        video.src = url;
      } else {
        clearTimeout(timeout);
        resolve(); // No verification needed for other types
      }
    });
  }

  _detectType(url) {
    const ext = url.split('.').pop()?.toLowerCase();
    if (['jpg', 'jpeg', 'png', 'gif', 'webp', 'svg'].includes(ext)) return 'image';
    if (['mp3', 'wav', 'ogg', 'm4a', 'aac'].includes(ext)) return 'audio';
    if (['mp4', 'webm', 'mov', 'm4v'].includes(ext)) return 'video';
    if (['json'].includes(ext)) return 'json';
    return 'text';
  }

  /**
   * Preload multiple assets in parallel
   * @param {(string|{url: string, isOptional?: boolean})[]} urls - Array of URLs or URL objects with optional metadata
   * @param {Object} options - Loading options
   */
  async preloadAssets(urls, options = {}) {
    const { onProgress } = options;
    let loaded = 0;
    const total = urls.length;

    // Normalize input to always work with objects internally
    const normalizedUrls = urls.map(item => {
      if (typeof item === 'string') {
        return { url: item, isOptional: false };
      }
      return { 
        url: item.url, 
        isOptional: item.isOptional || false 
      };
    });

    const results = await Promise.allSettled(
      normalizedUrls.map(async (item) => {
        try {
          // Pass isOptional flag to loadAsset
          const result = await this.loadAsset(item.url, { ...options, isOptional: item.isOptional });
          loaded++;
          if (onProgress) {
            onProgress(loaded / total, { loaded, total, current: item.url });
          }
          return { url: item.url, result, success: true, isOptional: item.isOptional };
        } catch (error) {
          loaded++;
          
          // loadAsset now handles logging based on isOptional flag
          if (onProgress) {
            onProgress(loaded / total, { loaded, total, current: item.url, error });
          }
          return { url: item.url, error, success: false, isOptional: item.isOptional };
        }
      })
    );

    // Only count/warn about required assets that failed
    const failedRequired = results.filter(r => 
      (r.status === 'rejected' || !r.value?.success) && !r.value?.isOptional
    );
    
    if (failedRequired.length > 0) {
      console.warn(`[RUN:assets] ${failedRequired.length} required assets failed to load`);
      // Log the URLs of failed required assets for debugging
      failedRequired.forEach(r => {
        console.warn(`[RUN:assets] Failed required asset: ${r.value?.url}`);
      });
    }

    return results.map(r => r.value);
  }

  /**
   * Clean up blob URLs to prevent memory leaks
   */
  cleanup() {
    for (const blobUrl of this.blobUrls.values()) {
      URL.revokeObjectURL(blobUrl);
    }
    this.blobUrls.clear();
    this.cache.clear();
  }

  /**
   * Get a cached asset URL if available
   */
  async getCached(url) {
    const resolvedUrl = await this.rundotGameAPI.cdn.resolveAssetUrl(url);
    return this.cache.get(resolvedUrl);
  }
}

// Export as part of RundotGameAPI
if (typeof RundotGameAPI !== 'undefined') {
  RundotGameAPI.assetLoader = new RundotGameAssetLoader();
  
  // Convenience methods
  RundotGameAPI.loadAsset = (url, options) => RundotGameAPI.assetLoader.loadAsset(url, options);
  RundotGameAPI.preloadAssets = (urls, options) => RundotGameAPI.assetLoader.preloadAssets(urls, options);
  RundotGameAPI.cleanupAssets = () => RundotGameAPI.assetLoader.cleanup();
}

// Export initialization function for RUN.world API
export function initializeAssetLoader(rundotGameApi, createProxiedMethod) {
  // Create the asset loader instance
  const assetLoader = new RundotGameAssetLoader();
  
  // Set the RundotGameAPI reference for platform detection
  assetLoader.setRundotGameAPI(rundotGameApi);
  
  // Add the instance to the API (not proxied)
  rundotGameApi._assetLoader = assetLoader;
  
  // Also expose as public assetLoader property as documented in the API
  rundotGameApi.assetLoader = assetLoader;
  
  // Add convenience methods using createProxiedMethod if available
  if (createProxiedMethod) {
    rundotGameApi.loadAsset = createProxiedMethod('loadAsset', function(url, options) {
      return assetLoader.loadAsset(url, options);
    });
    
    rundotGameApi.preloadAssets = createProxiedMethod('preloadAssets', function(urls, options) {
      return assetLoader.preloadAssets(urls, options);
    });
    
    rundotGameApi.cleanupAssets = createProxiedMethod('cleanupAssets', function() {
      return assetLoader.cleanup();
    });
  } else {
    // Fallback for environments without createProxiedMethod
    rundotGameApi.loadAsset = function(url, options) {
      return assetLoader.loadAsset(url, options);
    };
    
    rundotGameApi.preloadAssets = function(urls, options) {
      return assetLoader.preloadAssets(urls, options);
    };
    
    rundotGameApi.cleanupAssets = function() {
      return assetLoader.cleanup();
    };
  }
  
  // Also expose on global RundotGameAPI for backward compatibility
  if (typeof window !== 'undefined' && window.RundotGameAPI) {
    window.RundotGameAPI.loadAsset = rundotGameApi.loadAsset;
    window.RundotGameAPI.preloadAssets = rundotGameApi.preloadAssets;
    window.RundotGameAPI.cleanupAssets = rundotGameApi.cleanupAssets;
  }
} 