/**
 * Hosted-environment detection: does a RUN host own this game's mount?
 *
 * The answer decides which Host implementation the SDK builds — `RemoteHost`
 * (postMessage RPC to the venus client / Telegram shell) or `MockHost` /
 * `PlaygroundHost` (self-contained, no peer). Get it wrong in the "hosted"
 * direction and the game hangs forever on a handshake nobody answers; get it
 * wrong the other way and a real player silently plays against mock data.
 *
 * So the signal must be one a host DELIBERATELY emits, never one inferred
 * from the ambient environment:
 *
 *   - Web hosts (browser client, Electron `app://run.world`, Fire TV shell,
 *     Telegram mini-app) mount the game in an iframe whose URL carries the
 *     reserved bootstrap params. The generated bootstrap script records that
 *     as `__rundotConfig.hosted` before any other SDK code runs.
 *   - Native hosts (iOS/Android) mount in a react-native-webview, which
 *     defines `window.ReactNativeWebView` in the page. That global is proof
 *     on its own — the native path passes the game URL through untouched.
 *
 * Nothing else counts. In particular the URL's *shape* is not a signal: the
 * Studio preview serves builds from `/preview/{projectId}/__build/{buildId}/`,
 * which is indistinguishable from a legacy CDN path, and an earlier
 * path-segment heuristic read that as "hosted" — so every Studio preview built
 * a `RemoteHost`, waited on a handshake the preview pane never answers, and
 * rendered a permanently black frame. Any future surface that embeds a game
 * without being a host (a docs demo, a share card, a new IDE pane) would have
 * hit the same wall.
 */

/**
 * The mount param a web host always sets. Read here first-hand rather than via
 * `window.__rundotConfig`: that object is published by the generated libraries
 * bootstrap, which `generateBundle` emits only when the libraries plugin is
 * enabled AND at least one embedded library resolved. A game built with
 * `RUNDOT_GAME_DISABLE_EMBEDDED_LIBS=true` (the template's `build:bundled`
 * script) or one importing no embedded library ships without it — and reading
 * hosting off an artifact that may not exist would drop a real player onto
 * MockHost inside a live host, silently serving mock data.
 */
export const HOST_MOUNT_PARAM = '_pid'

/** The slice of `window` this decision reads. Kept minimal so tests pass a plain object. */
export interface HostEnvironmentWindow {
  location?: { search?: string }
  ReactNativeWebView?: unknown
}

/**
 * Escape hatch for running a hosted mount against the mock host (`?forceLocal=true`).
 * Explicit and caller-supplied, like every other signal here.
 */
function mountParams(win: HostEnvironmentWindow): URLSearchParams | null {
  try {
    return new URLSearchParams(win.location?.search ?? '')
  } catch {
    return null
  }
}

/**
 * True when a RUN host mounted this game and will answer the SDK's handshake.
 *
 * @param win The game's `window`, or undefined outside a browser (SSR/tests).
 */
export function isInsideHostedEnvironment(win: HostEnvironmentWindow | undefined): boolean {
  if (!win) return false
  const params = mountParams(win)
  // Escape hatch for running a hosted mount against the mock host. Explicit and
  // caller-supplied, like every other signal here.
  if (params?.get('forceLocal') === 'true') return false
  if (typeof win.ReactNativeWebView !== 'undefined') return true
  return params?.has(HOST_MOUNT_PARAM) === true
}
