import { RundotGameMessageId } from '../RundotGameMessageId.ts'

const HEARTBEAT_INTERVAL_MS = 10_000
const BYTES_PER_MB = 1_048_576

const LIFECYCLE_PAUSE_TYPES: ReadonlySet<string> = new Set([
  RundotGameMessageId.SLEEP,
  RundotGameMessageId.PAUSE,
])

const LIFECYCLE_RESUME_TYPES: ReadonlySet<string> = new Set([
  RundotGameMessageId.AWAKE,
  RundotGameMessageId.RESUME,
])

export interface HeartbeatPayload {
  uptimeMs: number
  heapUsedMB: number | null
  heapTotalMB: number | null
  heapLimitMB: number | null
  fps: number | null
  domNodeCount: number | null
}

interface PerformanceMemory {
  usedJSHeapSize: number
  totalJSHeapSize: number
  jsHeapSizeLimit: number
}

function getPerformanceMemory(): PerformanceMemory | null {
  if (
    typeof performance !== 'undefined' &&
    'memory' in performance &&
    performance.memory != null
  ) {
    return performance.memory as PerformanceMemory
  }
  return null
}

function bytesToMB(bytes: number): number {
  return Math.round((bytes / BYTES_PER_MB) * 100) / 100
}

function getDomNodeCount(): number | null {
  if (typeof document !== 'undefined') {
    return document.getElementsByTagName('*').length
  }
  return null
}

export interface HeartbeatTransport {
  sendHeartbeat(payload: HeartbeatPayload): void
}

export class PostMessageHeartbeatTransport implements HeartbeatTransport {
  private instanceId: string

  constructor(instanceId: string) {
    this.instanceId = instanceId
  }

  sendHeartbeat(payload: HeartbeatPayload): void {
    const cfg =
      (typeof window !== 'undefined' && (window as any).__rundotConfig) || null
    const nonce: string = (cfg && cfg.nonce) || ''
    const parentOrigin: string = (cfg && cfg.parentOrigin) || '*'

    const message = JSON.stringify({
      type: RundotGameMessageId.HEARTBEAT,
      direction: 'H5_TO_APP',
      data: payload,
      instanceId: this.instanceId,
      timestamp: Date.now(),
      ...(nonce ? { nonce } : {}),
    })

    try {
      const rn = (window as any).ReactNativeWebView
      if (rn) {
        rn.postMessage(message)
      } else {
        // Target parent's specific origin instead of '*'.
        window.parent.postMessage(message, parentOrigin)
      }
    } catch (_) {
      // Silently ignore — host may be unavailable
    }
  }
}

export class HeartbeatService {
  private readonly transport: HeartbeatTransport
  private readonly startTime: number = Date.now()

  private intervalId: ReturnType<typeof setInterval> | null = null
  private rafId: number | null = null
  private frameCount: number = 0
  private lastTickTime: number = Date.now()
  private running: boolean = false

  private readonly onMessage: (event: MessageEvent) => void

  constructor(transport: HeartbeatTransport) {
    this.transport = transport

    this.onMessage = (event: MessageEvent) => {
      const cfg =
        (typeof window !== 'undefined' && (window as any).__rundotConfig) || null
      const expectedParentOrigin: string = (cfg && cfg.parentOrigin) || ''
      const expectedNonce: string = (cfg && cfg.nonce) || ''

      const isRnBridgeEvent =
        event.origin === '' && (event as any).source == null
      if (!isRnBridgeEvent) {
        if (expectedParentOrigin && event.origin !== expectedParentOrigin) {
          return
        }
        if (typeof window !== 'undefined' && event.source !== window.parent) {
          return
        }
      }

      let type: string | undefined
      let nonce: string | undefined
      try {
        const data = typeof event.data === 'string' ? JSON.parse(event.data) : event.data
        type = data?.type
        nonce = data?.nonce
      } catch {
        return
      }
      if (!type) return
      if (expectedNonce && nonce !== expectedNonce) return

      if (LIFECYCLE_PAUSE_TYPES.has(type)) {
        this.pause()
      } else if (LIFECYCLE_RESUME_TYPES.has(type)) {
        this.resume()
      } else if (type === RundotGameMessageId.QUIT) {
        this.stop()
      }
    }
  }

  attach(): void {
    if (typeof window !== 'undefined') {
      window.addEventListener('message', this.onMessage)
    }
  }

  start(): void {
    if (this.running) return
    this.running = true
    this.lastTickTime = Date.now()
    this.frameCount = 0
    this.startRafLoop()
    this.intervalId = setInterval(() => this.tick(), HEARTBEAT_INTERVAL_MS)
  }

  stop(): void {
    this.running = false
    this.stopInterval()
    this.stopRafLoop()

    if (typeof window !== 'undefined') {
      window.removeEventListener('message', this.onMessage)
    }
  }

  isRunning(): boolean {
    return this.running
  }

  collect(): HeartbeatPayload {
    const now = Date.now()
    const elapsedSinceLastTick = now - this.lastTickTime

    let fps: number | null = null
    if (elapsedSinceLastTick > 0 && this.frameCount > 0) {
      fps = Math.round((this.frameCount / (elapsedSinceLastTick / 1000)) * 10) / 10
    }

    const mem = getPerformanceMemory()

    return {
      uptimeMs: now - this.startTime,
      heapUsedMB: mem ? bytesToMB(mem.usedJSHeapSize) : null,
      heapTotalMB: mem ? bytesToMB(mem.totalJSHeapSize) : null,
      heapLimitMB: mem ? bytesToMB(mem.jsHeapSizeLimit) : null,
      fps,
      domNodeCount: getDomNodeCount(),
    }
  }

  private tick(): void {
    const payload = this.collect()
    this.frameCount = 0
    this.lastTickTime = Date.now()
    try {
      this.transport.sendHeartbeat(payload)
    } catch (_) {
      // Non-fatal — host may be unavailable
    }
  }

  private pause(): void {
    this.stopInterval()
    this.stopRafLoop()
  }

  private resume(): void {
    if (this.running) {
      this.lastTickTime = Date.now()
      this.frameCount = 0
      this.startRafLoop()
      if (this.intervalId == null) {
        this.intervalId = setInterval(() => this.tick(), HEARTBEAT_INTERVAL_MS)
      }
    } else {
      this.start()
    }
  }

  private startRafLoop(): void {
    if (this.rafId != null) return
    if (typeof requestAnimationFrame === 'undefined') return
    const loop = (): void => {
      this.frameCount++
      this.rafId = requestAnimationFrame(loop)
    }
    this.rafId = requestAnimationFrame(loop)
  }

  private stopRafLoop(): void {
    if (this.rafId != null && typeof cancelAnimationFrame !== 'undefined') {
      cancelAnimationFrame(this.rafId)
    }
    this.rafId = null
  }

  private stopInterval(): void {
    if (this.intervalId != null) {
      clearInterval(this.intervalId)
      this.intervalId = null
    }
  }
}
