import { RundotGameAPI } from '../rundot-game-api/types'
import { Host } from '../Host'

export function initializeContext(rundotGameApi: RundotGameAPI, host: Host) {
  rundotGameApi.context = host.context || {
    initializeAsleep: false,
    launchParams: {},
    shareParams: {},
    notificationParams: {},
  }

  host.onNotificationParamsUpdate?.((params) => {
    if (rundotGameApi.context) {
      rundotGameApi.context.notificationParams = params
    }
  })

  // Signal the host that the subscription above is registered. The host uses
  // this as the exact gate for "live notification push will be received";
  // taps arriving before this ACK get stashed and replayed on next INIT_SDK
  // instead of being dropped silently on the SDK's RpcClient.
  host.notifyNotificationParamsSubscribeReady?.()
}
